class AccountSpec extends AnyFunSuite with GivenWhenThen {
  test("withdraw within balance reduces the balance") {
    Given("an account with 100")          // Arrange
    val account = Account(100)

    When("30 is withdrawn")               // Act
    val ok = account.withdraw(30)

    Then("the balance is 70")             // Assert
    assert(ok)
    assert(account.balance == 70)
  }
}

